CREATE DATABASE IF NOT EXISTS registrar_queue_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE registrar_queue_db;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','staff','student') NOT NULL DEFAULT 'student',status ENUM('active','disabled') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS student_profiles(user_id BIGINT UNSIGNED PRIMARY KEY,student_number VARCHAR(50) UNIQUE,course VARCHAR(100),year_level VARCHAR(30),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS services(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,code VARCHAR(12) NOT NULL UNIQUE,description TEXT,estimated_minutes INT NOT NULL DEFAULT 10,is_active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS service_counters(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,location VARCHAR(120),is_active TINYINT(1) DEFAULT 1);
CREATE TABLE IF NOT EXISTS counter_assignments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,counter_id BIGINT UNSIGNED NOT NULL,staff_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,is_active TINYINT(1) DEFAULT 1,FOREIGN KEY(counter_id) REFERENCES service_counters(id),FOREIGN KEY(staff_id) REFERENCES users(id),FOREIGN KEY(service_id) REFERENCES services(id));
CREATE TABLE IF NOT EXISTS daily_queue_sequences(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,service_id BIGINT UNSIGNED NOT NULL,queue_date DATE NOT NULL,last_number INT UNSIGNED DEFAULT 0,UNIQUE KEY uq_service_day(service_id,queue_date),FOREIGN KEY(service_id) REFERENCES services(id));
CREATE TABLE IF NOT EXISTS queues(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,queue_number VARCHAR(30) NOT NULL,sequence_number INT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,counter_id BIGINT UNSIGNED NULL,staff_id BIGINT UNSIGNED NULL,queue_date DATE NOT NULL,status ENUM('Waiting','Called','Processing','Completed','Skipped','Cancelled','Absent') DEFAULT 'Waiting',requested_at DATETIME DEFAULT CURRENT_TIMESTAMP,called_at DATETIME NULL,started_at DATETIME NULL,completed_at DATETIME NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_ticket(service_id,queue_date,sequence_number),INDEX idx_wait(service_id,queue_date,status),FOREIGN KEY(service_id) REFERENCES services(id),FOREIGN KEY(student_id) REFERENCES users(id),FOREIGN KEY(counter_id) REFERENCES service_counters(id) ON DELETE SET NULL,FOREIGN KEY(staff_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS queue_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,queue_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NULL,old_status VARCHAR(30),new_status VARCHAR(30) NOT NULL,note VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(queue_id) REFERENCES queues(id) ON DELETE CASCADE,FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(150),message TEXT,is_read TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS announcements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,body TEXT NOT NULL,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS operating_hours(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,day_of_week TINYINT UNSIGNED UNIQUE,opens_at TIME,closes_at TIME,is_open TINYINT(1) DEFAULT 1);
CREATE TABLE IF NOT EXISTS holidays(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,holiday_date DATE UNIQUE,name VARCHAR(150));
CREATE TABLE IF NOT EXISTS system_settings(setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT);
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED NULL,action VARCHAR(120),details JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL);
